 juce::ScopedJuceInitialiser_GUI init;Processor p(false);p.trackOffline=true;auto a=std::make_shared<AudioData>();a->rate=48000;a->path="/tmp/sg-padding.wav";a->buffer.setSize(2,48000*4);for(int ch=0;ch<2;++ch)for(int n=0;n<a->buffer.getNumSamples();++n)a->buffer.setSample(ch,n,.2f*std::sin(n*.031+ch));p.audio=a;p.split(4,false);p.trackMode=p.trackGridReady=p.trackGridEdited=true;p.trackGrid.bpm=120;p.trackGrid.anchors={{0,0},{48000.*4,8}};p.trackStemsEnabled=false;p.trackLoop=true;p.trackLoopStart=-4;p.trackLoopEnd=12;p.hasHost=true;p.hostBpm=120;p.normaliseEnabled=false;
 for(bool raw:{true,false}){p.trackExportRaw=raw;auto result=renderLoopAudio(AudioExportSnapshot::capture(p));if(result.getNumSamples()!=48000*8)return 2190;for(int ch=0;ch<2;++ch){for(int n=0;n<48000*2-10;++n)if(result.getSample(ch,n)!=0)return 2191;for(int n=48000*6+10;n<result.getNumSamples();++n)if(result.getSample(ch,n)!=0)return 2192;float error=0;for(int n=1000;n<48000*4-1000;++n)error=std::max(error,std::abs(result.getSample(ch,n+48000*2)-a->buffer.getSample(ch,n)));if(error>1e-4)return 2193;}}
