int runFullLiveTrackCheck(const char* path){juce::ScopedJuceInitialiser_GUI init;juce::AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(juce::File(path)));if(!reader)return 2210;juce::AudioBuffer<float> clip(2,(int)reader->lengthInSamples);reader->read(&clip,0,clip.getNumSamples(),0,true,true);auto buffer=std::make_shared<juce::AudioBuffer<float>>(2,48000*110);for(int ch=0;ch<2;++ch)for(int n=0;n<buffer->getNumSamples();++n)buffer->setSample(ch,n,clip.getSample(ch,n%clip.getNumSamples()));TrackStemWorker worker;worker.setSource(buffer,48000,true);worker.wantedFrame=44100*130;auto end=juce::Time::getMillisecondCounter()+90000;while(!worker.complete&&worker.status!=3&&juce::Time::getMillisecondCounter()<end)juce::Thread::sleep(10);auto window=worker.result();if(!worker.complete||!window||window->chunks.size()<=TrackStemWorker::maxChunks||!window->at(0)||!window->at(44100*109)){std::cerr<<"Full Live state: complete="<<worker.complete<<" preparation="<<worker.preparation<<" status="<<worker.status<<" chunks="<<(window?window->chunks.size():0)<<"\n";return 2211;}auto before=window;worker.wantedFrame=44100*100;juce::Thread::sleep(100);if(worker.result()!=before){auto after=worker.result();std::cerr<<"Completed cache changed: before="<<before->chunks.size()<<" after="<<(after?after->chunks.size():0)<<" before coverage="<<before->covers(0,44100*110)<<" before 100s="<<(before->at(44100*100)!=nullptr)<<" complete="<<worker.complete<<" progress="<<worker.preparation<<"\n";return 2212;}worker.setSource({},48000,false);end=juce::Time::getMillisecondCounter()+3000;while(worker.result()&&juce::Time::getMillisecondCounter()<end)juce::Thread::sleep(10);if(worker.result())return 2213;std::cout<<"110-second full Live PCM retained beyond old rolling cache limit; beginning/end instantly available; completed preparation idles; unload releases cache passed\n";return 0;}
